final class ModularExponentiation {
    private ModularExponentiation() {
        // Utility class.
    }

    public static int powMod(int base, int exponent, int modulus) {
        validateInputs(exponent, modulus);

        int result = 1;
        int currentBase = base;
        int currentExponent = exponent;

        while (currentExponent > 0) {
            if ((currentExponent & 1) == 1) {
                result = multiplyMod(result, currentBase, modulus);
            }
            currentBase = multiplyMod(currentBase, currentBase, modulus);
            currentExponent >>= 1;
        }

        return result;
    }

    private static void validateInputs(int exponent, int modulus) {
        if (modulus <= 0) {
            throw new IllegalArgumentException("Modulus must be positive.");
        }
        if (exponent < 0) {
            throw new IllegalArgumentException("Exponent must be non-negative.");
        }
    }

    private static int multiplyMod(int left, int right, int modulus) {
        return (int) ((1L * left * right) % modulus);
    }

    public static void main(String[] args) {
        ModularExponentiationApp.main(args);
    }
}

public final class ModularExponentiationApp {
    private ModularExponentiationApp() {
        // Application entrypoint only.
    }

    public static void main(String[] args) {
        ModularExponentiationRequest request = ModularExponentiationRequest.fromArgs(args);

        System.out.println(ModularExponentiation.powMod(
            request.base(),
            request.exponent(),
            request.modulus()
        ));
    }
}

public final class ModularExponentiationRequest {
    private static final int DEFAULT_BASE = 3;
    private static final int DEFAULT_EXPONENT = 2;
    private static final int DEFAULT_MODULUS = 4;

    private final int base;
    private final int exponent;
    private final int modulus;

    private ModularExponentiationRequest(int base, int exponent, int modulus) {
        this.base = base;
        this.exponent = exponent;
        this.modulus = modulus;
    }

    public static ModularExponentiationRequest fromArgs(String[] args) {
        if (args.length == 0) {
            return defaults();
        }

        if (args.length != 3) {
            throw new IllegalArgumentException(
                "Usage: java ModularExponentiationApp [base exponent modulus]"
            );
        }

        return new ModularExponentiationRequest(
            Integer.parseInt(args[0]),
            Integer.parseInt(args[1]),
            Integer.parseInt(args[2])
        );
    }

    private static ModularExponentiationRequest defaults() {
        return new ModularExponentiationRequest(DEFAULT_BASE, DEFAULT_EXPONENT, DEFAULT_MODULUS);
    }

    public int base() {
        return base;
    }

    public int exponent() {
        return exponent;
    }

    public int modulus() {
        return modulus;
    }
}

